package com.citacloud.app.models;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDateTime; import java.util.UUID;
@Entity @Table(name="movimientos_caja") public class MovimientoCaja {
 @Id @GeneratedValue private UUID id; @Column(name="empresa_id",nullable=false) private UUID empresaId; @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="sucursal_id",nullable=false) private Sucursal sucursal; @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="caja_id") private Caja caja; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="sesion_caja_id",nullable=false) private SesionCaja sesion; private String numero; private String tipo; private String direccion; @Column(name="metodo_pago") private String metodoPago; private BigDecimal monto; @Column(name="clave_idempotencia") private String claveIdempotencia; @OneToOne(fetch=FetchType.LAZY) @JoinColumn(name="pago_id") private Pago pago; @OneToOne(fetch=FetchType.LAZY) @JoinColumn(name="reembolso_id") private ReembolsoPago reembolso; private String concepto; private String referencia; private String notas; private String estado="ACTIVE"; @Column(name="creado_por") private UUID creadoPor; @Column(name="creado_en") private LocalDateTime creadoEn=LocalDateTime.now(); @Column(name="revertido_por") private UUID revertidoPor; @Column(name="revertido_en") private LocalDateTime revertidoEn; @Column(name="motivo_reversion") private String motivoReversion;
 public UUID getId(){return id;} public UUID getEmpresaId(){return empresaId;} public void setEmpresaId(UUID v){empresaId=v;} public Sucursal getSucursal(){return sucursal;} public void setSucursal(Sucursal v){sucursal=v;} public Caja getCaja(){return caja;} public void setCaja(Caja v){caja=v;} public SesionCaja getSesion(){return sesion;} public void setSesion(SesionCaja v){sesion=v;} public String getNumero(){return numero;} public void setNumero(String v){numero=v;} public String getTipo(){return tipo;} public void setTipo(String v){tipo=v;} public String getDireccion(){return direccion;} public void setDireccion(String v){direccion=v;} public String getMetodoPago(){return metodoPago;} public void setMetodoPago(String v){metodoPago=v;} public BigDecimal getMonto(){return monto;} public void setMonto(BigDecimal v){monto=v;} public String getClaveIdempotencia(){return claveIdempotencia;} public void setClaveIdempotencia(String v){claveIdempotencia=v;} public Pago getPago(){return pago;} public void setPago(Pago v){pago=v;} public ReembolsoPago getReembolso(){return reembolso;} public void setReembolso(ReembolsoPago v){reembolso=v;} public String getConcepto(){return concepto;} public void setConcepto(String v){concepto=v;} public String getReferencia(){return referencia;} public void setReferencia(String v){referencia=v;} public String getNotas(){return notas;} public void setNotas(String v){notas=v;} public String getEstado(){return estado;} public void setEstado(String v){estado=v;} public UUID getCreadoPor(){return creadoPor;} public void setCreadoPor(UUID v){creadoPor=v;} public LocalDateTime getCreadoEn(){return creadoEn;} public void setCreadoEn(LocalDateTime v){creadoEn=v;} public void revertir(UUID usuario,String motivo){estado="REVERSED";revertidoPor=usuario;revertidoEn=LocalDateTime.now();motivoReversion=motivo;}
}
